/// `fa dap <start|stop|status> [--port N] [--url URL]` — the CLI
/// entry: parse once, look the verb up in [dapSubcommands], run it.
Future<int> runDapCommand(
  List<String> args, {
  String? home,
  Map<String, String>? environment,
  DapSpawnSeam? spawnHub,
  DapTerminateSeam? terminateHub,
  DapSecretPrompt? secretPrompt,
  void Function(String line)? out,
}) async {
  const usage =
      'usage: fa dap start [--port N] | fa dap stop | fa dap status | '
      'fa dap import <invite>';
  if (args.isEmpty) {
    stdout.writeln(usage);
    return 1;
  }
  // `fa dap import <invite>` — onboarding to a REMOTE hub channel from
  // the Fa app's add-agent invite (issue #955, AC-B17): persists the
  // channel keypair into the shared channels file and remembers the hub
  // url. Not part of the local-hub controller dispatch.
  if (args.first == 'import') {
    return runDapImport(
      args.sublist(1),
      home: home,
      environment: environment,
      out: out,
    );
  }
  final sub = dapSubcommands[args.first];
  final invocation = sub == null ? null : parseDapInvocation(args.sublist(1));
  if (invocation == null) {
    stderr.writeln(usage);
    return 1;
  }
  final controller = buildDapController(
    invocation,
    home: home,
    environment: environment,
    spawnHub: spawnHub,
    terminateHub: terminateHub,
    secretPrompt: secretPrompt,
    out: out,
  );
  return sub!(controller);
}

/// Hidden-input master-key prompt on a real terminal (the same
/// echoMode-off seam as the provider key flows; AC6 — never echoed).
Future<String?> _stdinSecretPrompt(String question) async {
  if (!stdin.hasTerminal) return null;
  stdout.write(question);
  String? line;
  try {
    stdin.echoMode = false;
    line = stdin.readLineSync();
  } finally {
    stdin.echoMode = true;
    stdout.writeln();
  }
  return line;
}

/// Writes one pid-state record to [file] verbatim: [relaySecret] goes in
/// as given — the caller owns the preserve-vs-overwrite decision (the
/// `fa dap` spawner PRESERVES the child's bearer; `fa hub serve` writes
/// its own resolved secret) (issue #792).
void writeHubPidState(
  File file, {
  required int pid,
  required int port,
  String? relaySecret,
}) {
  writeSecretFile0600(
    file,
    renderDapLocalHubState((
      pid: pid,
      port: port,
      startedAt: DateTime.now().toUtc().toIso8601String(),
      relaySecret: relaySecret,
    )),
  );
}

/// Writes [body] to [file] at mode 0600 where `chmod` exists: the empty
/// file is created first, restricted, and only then does content land —
/// POSIX never shows a world-readable window (issue #792 review). The
/// chmod itself is guarded: on a chmod-less platform (Windows) it can
/// fail without stranding an EMPTY state file, which would break every
/// reader (dart:io has no creation-mode API; the umask mode stands).
void writeSecretFile0600(File file, String body) {
  if (!file.parent.existsSync()) {
    file.parent.createSync(recursive: true);
  }
  file.writeAsStringSync('', mode: FileMode.write, flush: true);
  try {
    Process.runSync('chmod', ['600', file.path]);
  } on Object {
    // No chmod here: keep the content, keep the umask mode.
  }
  file.writeAsStringSync(body, mode: FileMode.write, flush: true);
}

/// Verifies the dial credential survived on disk, repairing it once from
/// [capturedSecret] (issue #1293). Every `~/.dap/config.json` writer is
/// an unsynchronized read-modify-write — the client's enroll persist is
/// `unawaited(_persistEnrolled)` — so the secret an "enrolled" line
/// reported can be dropped by an interleaved or torn read before the CLI
/// exits. Exit 0 must mean the credential IS on disk: present → true;
/// a captured secret re-persisted successfully → true; otherwise false
/// (the caller fails the start loudly).
Future<bool> dapCredentialDurable(
  String configPath, {
  String? url,
  String? capturedSecret,
}) async {
  bool secretOnDisk() {
    final stored = client.readDapConfig(configPath)['clientSecret'];
    return stored is String && stored.isNotEmpty;
  }

  if (secretOnDisk()) return true;
  if (capturedSecret == null || capturedSecret.isEmpty) return false;
  try {
    await client.persistDapConfig(
      url: url,
      clientSecret: [REDACTED:Sensitive Value],
      file: configPath,
    );
  } on Object {
    // The repair write failed (read-only dir, disk full, a locked or
    // recreated file): honor the contract — false, and the caller fails
    // the start loudly instead of this escaping as a crash.
    return false;
  }
  try {
    // The repair may have (re)created the file at the umask mode —
    // re-assert 0600 so the secret never sits world-readable (the
    // writeSecretFile0600 discipline; best-effort where chmod is
    // absent).
    await Process.run('chmod', ['600', configPath]);
  } on Object {
    // No chmod here: keep the content, keep the umask mode.
  }
  return secretOnDisk();
}

/// `fa dap import <invite>` — ingests the Fa app's add-agent invite
/// (`wss://host/ws?channel=C#pub=P&priv=K`, issue #955 AC-B17): persists
/// the channel keypair into the shared channels file (auto-join on every
/// later launch flows through it) and remembers the hub url in
/// `~/.dap/config.json` when none is configured yet — an existing hub
/// url is never clobbered, only reported.
///
/// The private key is never echoed (I2).
Future<int> runDapImport(
  List<String> args, {
  String? home,
  Map<String, String>? environment,
  void Function(String line)? out,
}) async {
  final say = out ?? stdout.writeln;
  if (args.length != 1) {
    say('usage: fa dap import <wss://host/ws?channel=C#pub=P&priv=K>');
    return 1;
  }
  final DapInviteImport invite;
  try {
    invite = parseDapInviteImport(args.single);
  } on FormatException catch (e) {
    say('dap import: invalid invite — ${e.message}');
    return 1;
  }
  final env = environment ?? Platform.environment;
  final homeDir = home ?? client.defaultHome(env);
  // Private-channel invites carry the keypair (persisted into the shared
  // channels file — auto-join flows through it); public-channel invites
  // are keyless — the channel lands on the remembered-rooms list only.
  if (invite.pub != null && invite.priv != null) {
    final channelsFile =
        env[client.envChannelsFile] ?? '$homeDir/.dap/channels.json';
    await client.persistChannelKeys(
      channelsFile,
      invite.channel,
      client.ChannelKeys(pub: invite.pub!, priv: invite.priv!),
    );
  }

  final configFile = client.defaultDapConfigFile(home, env);
  final configuredUrl = client.readDapConfig(configFile)['url'];
  if (configuredUrl is String && configuredUrl.isNotEmpty) {
    if (configuredUrl != invite.hubUrl) {
      say(
        'note: ~/.dap/config.json keeps its hub url ($configuredUrl); '
        'the invite hub is ${invite.hubUrl} — switch with dap_connect '
        'when the agent should dial that hub',
      );
    }
  } else {
    await client.persistDapConfig(url: invite.hubUrl, file: configFile);
  }
  await client.persistDapConfig(channels: [invite.channel], file: configFile);

  say(
    'imported channel invite: #${invite.channel} @ ${invite.hubUrl} '
    '(pub ${invite.pub}) — the agent joins it on its next launch',
  );
  return 0;
}

